candidates.raw:
    adcs_quat_t qc, qt, qcur_conj, qrel;
    double w, angle;

    if ((current == NULL) || (target == NULL) || (required_rate == NULL) || (margin == NULL)) {
        if (required_rate != NULL) {
            *required_rate = INFINITY;
        }
        if (margin != NULL) {
            *margin = -INFINITY;
        }
        return ADCS_E_NULL;
    }

    if ((!isfinite(current->w)) || (!isfinite(current->x)) || (!isfinite(current->y)) ||
        (!isfinite(current->z)) || (!isfinite(target->w)) || (!isfinite(target->x)) ||
        (!isfinite(target->y)) || (!isfinite(target->z)) || (!isfinite(duration)) ||
        (duration <= 0.0) || (!isfinite(max_rate)) || (max_rate < 0.0)) {
        *required_rate = INFINITY;
        *margin = -INFINITY;
        return ADCS_E_RANGE;
    }

    if ((adcs_quat_normalize(current, &qc) != ADCS_OK) ||
        (adcs_quat_normalize(target, &qt) != ADCS_OK)) {
        *required_rate = INFINITY;
        *margin = -INFINITY;
        return ADCS_E_RANGE;
    }

    qcur_conj = adcs_quat_conjugate(&qc);
    qrel = adcs_quat_multiply(&qt, &qcur_conj);

    w = fabs(qrel.w);
    w = ADCS_CLAMP(w, 0.0, 1.0);
    angle = 2.0 * acos(w);

    *required_rate = angle / duration;
    *margin = max_rate - *required_rate;

    return ADCS_OK;
}

